// Reads the student's stored dates and computes days remaining
// against each deadline. Replace this stub with a real read from wherever
// you store the user's opt_start / stem_start dates (a small JSON file,
// SQLite, or the same Chroma metadata store used for the RAG pipeline).

const optStart = new Date($env.OPT_START_DATE); // e.g. '2026-12-14'
const stemStart = $env.STEM_START_DATE ? new Date($env.STEM_START_DATE) : null;
const today = new Date();

function daysBetween(a, b) {
  return Math.round((b - a) / (1000 * 60 * 60 * 24));
}

const alerts = [];

const daysSinceOptStart = daysBetween(optStart, today);
const unemploymentWarningDay = 60; // warn at 60, hard limit is 90
const unemploymentHardLimitDay = 90;

if (daysSinceOptStart >= unemploymentWarningDay && daysSinceOptStart < unemploymentHardLimitDay) {
  alerts.push(`Warning: you are ${daysSinceOptStart} days into your OPT unemployment window. The 90-day hard limit is approaching.`);
}

if (stemStart) {
  const reportPoints = [
    { months: 6, label: '6-month STEM OPT report' },
    { months: 12, label: '12-month STEM OPT report + evaluation' },
    { months: 18, label: '18-month STEM OPT report' },
    { months: 24, label: '24-month STEM OPT report + final evaluation' },
  ];
  for (const point of reportPoints) {
    const dueDate = new Date(stemStart);
    dueDate.setMonth(dueDate.getMonth() + point.months);
    const daysUntilDue = daysBetween(today, dueDate);
    if (daysUntilDue > 0 && daysUntilDue <= 30) {
      alerts.push(`Reminder: your ${point.label} is due in ${daysUntilDue} days (${dueDate.toISOString().slice(0,10)}).`);
    }
  }
}

return alerts.map(text => ({ json: { alertText: text } }));
